// Native Homebox owns inventory and authentication. This page holds no credentials.
const pages=[['overview','Overview',false],['equipment','Equipment',false],['checkout-cart','Checkout cart',false],['loans','Loans & notes',false],['people','People & badges',true],['workshop','Workshop & storage',false],['imports','Imports',true],['labels','Labels',true],['recovery','Recovery',true],['system','System',true]];
