let context=null,current='overview',routeVersion=0,dialogEpoch=0,itemTabVersion=0,busy=false,dialogDirty=false,dialogCommit=false,activeItem=null,layoutState=null,layoutDraft=null,layoutDirty=false,layoutSelected=null,importBatch=null,importSelectionRevision=0;
let equipment=[],locations=[],loans=[],members=[],badges=[],types=[],equipmentQuery='',equipmentFilter='',selection=new Set(),labelSelection=new Set();
const clone=v=>JSON.parse(JSON.stringify(v));
function uuid(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const s=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return [s.slice(0,8),s.slice(8,12),s.slice(12,16),s.slice(16,20),s.slice(20)].join('-')}
