function timestamp(value){if(!value)return 'Time unavailable';const date=new Date(/[zZ]|[+-]\d\d:?\d\d$/.test(value)?value:String(value).replace(' ','T')+'Z');if(Number.isNaN(date.getTime()))return 'Time unavailable';return new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(date)}
function manager(){return !!context?.manager}
function captureUi(){return {identity:context?.identity,route:routeVersion,dialog:dialogEpoch}}
function uiCurrent(token){return token.identity===context?.identity&&token.route===routeVersion&&token.dialog===dialogEpoch}
function scope(){return context?`${context.group.id}:${context.user.id}`:''}
function pending(){try{return JSON.parse(localStorage.getItem('workshop-pending:'+scope())||'[]')}catch{return []}}
function savePending(rows){localStorage.setItem('workshop-pending:'+scope(),JSON.stringify(rows))}
function removePending(key){savePending(pending().filter(p=>p.key!==key))}
async function api(path,data,identity=context?.identity){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),25000);try{const r=await fetch('/workshop-api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-Workshop-Identity':identity||''},body:data===undefined?undefined:JSON.stringify(data),signal:ctl.signal});const result=await r.json();if(path!=='context'&&identity!==context?.identity)throw Error('The signed-in account changed. Reload after checking your sign-in.');if(!r.ok){const err=Error(result.error||result.reason||'The request failed.');err.status=r.status;if(r.status===401||r.status===403&&path==='context')signedOut();throw err}return result}catch(e){if(e.name==='AbortError')throw Error('No confirmation received. Check the saved operation before repeating it.');throw e}finally{clearTimeout(timer)}}
function signedOut(){context=null;equipment=[];loans=[];members=[];badges=[];selection.clear();labelSelection.clear();layoutDraft=null;layoutDirty=false;importBatch=null;importSelectionRevision++;dialogDirty=false;dialogEpoch++;itemTabVersion++;if(dialog.open)dialog.close();dialogBody.replaceChildren();document.querySelector('#nav').replaceChildren();document.querySelector('#mobile-nav').replaceChildren();document.querySelector('#signed-name').textContent='Signed out';document.querySelector('#role').textContent='';document.querySelector('#collection').textContent='Homebox login required';view.replaceChildren();title('Sign in to Homebox','Use your Homebox account to open the workshop for its collection.');view.append(panel(link('Open Homebox sign-in','/'),button('Check my sign-in',start,'main')));routeVersion++}
async function refreshContext(){const previous=context?.identity,next=await api('context');if(previous!==context?.identity)throw Error('Your sign-in changed while its status was checked.');if(context&&(next.identity!==context.identity||next.manager!==context.manager)){signedOut();throw Error('Your Homebox account, session or workshop permission changed. Check your sign-in before continuing.')}context=next;return next}
async function write(path,data,label,subject=''){if(!manager())throw Error('This action requires Workshop manager permission.');if(busy)throw Error('Wait for the current confirmation to finish.');if(pending().some(p=>p.path===path&&p.subject===subject))throw Error('This action has an unconfirmed result. Open Recovery and check the saved operation.');busy=true;dialogCommit=true;let key;const owner=scope(),identity=context.identity;let sent=false;const frozen=Array.from(document.querySelectorAll('#dialog button:not([data-queue-stop]),#dialog input,#dialog select,#dialog textarea,#view button:not([data-queue-stop]),#view input,#view select,#view textarea')).map(control=>[control,control.disabled]);frozen.forEach(([control])=>control.disabled=true);try{key=data.request_key||uuid();await refreshContext();data={...data,request_key:key};savePending([...pending(),{key,path,label,subject,at:new Date().toISOString(),batch:data.id,index:data.index}]);sent=true;const result=await api(path,data,identity);if(scope()!==owner||context.identity!==identity)throw Error('The signed-in account changed. Check Recovery for the saved result.');removePending(key);return result}catch(error){if(sent)error.request_key=key;if(!sent&&scope()===owner)removePending(key);if(sent&&[400,409].includes(error.status)){try{const result=await api('operation/status',{request_key:key},identity);if(['not_started','cancelled'].includes(result.status))removePending(key)}catch{}}throw error}finally{busy=false;dialogCommit=false;frozen.forEach(([control,disabled])=>control.disabled=disabled)}}
async function unresolvedOperation(error,label){const key=error?.request_key;if(!key){toast(error.message||'The action could not be confirmed.');return}const body=node('div',null,'form');body.append(node('p',label+' may have reached Homebox. Its saved request identity is '+key+'. It will not be submitted again automatically.'));const check=button('Check saved result',async()=>{check.disabled=true;try{const result=await api('operation/status',{request_key:key});body.replaceChildren(node('p',label+' status: '+result.status+'.'));if(result.status==='completed')body.append(node('p','The saved operation completed. Refresh this page to see the updated borrowing or return status.'));else body.append(node('p','No new operation was submitted. Inspect Recovery before taking another action.'));body.append(button('Open Recovery',()=>{closeDialog(true);go('recovery')}))}catch(e){body.append(node('p','The saved status could not be checked: '+e.message+'. Open Recovery and check again; do not repeat the operation.'))}finally{check.disabled=false}});body.append(check,button('Open Recovery',()=>{closeDialog(true);go('recovery')}));openDialog('Check saved operation',body)}
function openDialog(name,...content){if(dialog.open)dialog.close();dialogEpoch++;itemTabVersion++;dialogDirty=false;document.querySelector('#dialog-title').textContent=name;dialogBody.replaceChildren(...content.filter(Boolean));dialog.showModal()}
function closeDialog(force=false){if(dialogCommit&&!force){toast('Wait for confirmation to finish.');return false}if(dialogDirty&&!force&&!window.confirm('Discard these unsaved edits?'))return false;dialogDirty=false;dialogEpoch++;itemTabVersion++;dialog.close();dialogBody.replaceChildren();return true}
document.querySelector('#dialog-close').onclick=()=>closeDialog();dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});
function renderNav(){document.querySelector('#collection').textContent=context.group.name;document.querySelector('#signed-name').textContent=context.user.name;document.querySelector('#role').replaceChildren(tag(manager()?'Workshop manager':'Member','role'));const nav=document.querySelector('#nav'),mobile=document.querySelector('#mobile-nav');nav.replaceChildren();mobile.replaceChildren();for(const [id,name,admin] of pages){if(admin&&!manager())continue;const b=button(name,()=>go(id),id===current?'selected':'');if(id===current)b.setAttribute('aria-current','page');nav.append(b);mobile.append(new Option(name,id))}mobile.value=current}
function pendingBanner(){const rows=pending();if(rows.length){const box=message(`${rows.length} action${rows.length===1?' has':'s have'} an unconfirmed result. Saved request identities prevent accidental duplicate creation or printing.`,'attention pending-banner');box.append(button('Check saved actions',()=>go('recovery')));view.prepend(box)}}
async function go(page,push=true){if(!context){signedOut();return}if(busy){toast('Wait for confirmation to finish.');return}if(layoutDirty&&page!=='workshop'&&!window.confirm('Discard unsaved layout changes?'))return;if(page!=='workshop'&&layoutDirty){layoutDirty=false;layoutDraft=null}if(dialog.open&&!closeDialog())return;if(pages.find(p=>p[0]===page)?.[2]&&!manager()){toast('This area requires Workshop manager permission.');page='overview';history.replaceState({page},'','#overview')}current=pages.some(p=>p[0]===page)?page:'overview';if(push&&location.hash!=='#'+current)history.pushState({page:current},'','#'+current);renderNav();const revision=++routeVersion;view.replaceChildren(node('p','Loading…','spinner'));try{await refreshContext();if(revision!==routeVersion)return;view.replaceChildren();await ({overview:overview,equipment:equipmentPage,'checkout-cart':checkoutCartPage,loans:loansPage,people:peoplePage,workshop:workshopPage,imports:importsPage,labels:labelsPage,recovery:recoveryPage,system:systemPage})[current](revision);if(revision!==routeVersion)return;pendingBanner();view.focus({preventScroll:true})}catch(error){if(revision===routeVersion){view.replaceChildren();title('Could not load this page',error.message);view.append(button('Try loading again',()=>go(current,false),'main'),link('Open Homebox','/'))}}}
document.querySelector('#mobile-nav').onchange=e=>go(e.target.value).catch(report);
window.addEventListener('popstate',()=>{go(location.hash.slice(1)||'overview',false).catch(report)});
window.addEventListener('storage',()=>{if(context)refreshContext().catch(report)});
window.addEventListener('focus',()=>{if(context&&!busy)refreshContext().catch(report)});
