setInterval(()=>{if(context&&!busy)refreshContext().catch(()=>{})},30000);
async function inventoryData(){const identity=context?.identity;const values=await Promise.all([api('equipment'),api('locations'),api('loans')]);if(identity!==context?.identity)return;[equipment,locations,loans]=values;}
function itemName(id){return equipment.find(e=>e.id===id)?.name||id}
function address(id){const parts=[],seen=new Set();let e=locations.find(e=>e.id===id);while(e&&!seen.has(e.id)){seen.add(e.id);parts.unshift(e.code||e.name);e=locations.find(p=>p.id===(e.parent_id||e.parent?.id))}return parts.join(' / ')||'Not assigned'}
function held(id){return loans.find(l=>l.entity_id===id)}
async function overview(revision){await inventoryData();const recover=manager()?await api('recovery'):[];if(revision!==routeVersion)return;title('Workshop overview','Start with equipment in use and work needing attention.');if(recover.length)view.append(message(`${recover.length} interrupted operation${recover.length===1?' needs':'s need'} review. Inspect saved outcomes before repeating changes or prints.`,'attention'));const split=node('div',null,'two'),loanPanel=panel(node('h2','Equipment in use')),reviewPanel=panel(node('h2','Before the next checkout'));for(const row of loans.slice(0,6)){const p=node('p');p.append(button(row.entity_name||itemName(row.entity_id),()=>showItem(row.entity_id,'loan')),node('small',row.borrower,'sub'));loanPanel.append(p)}if(!loans.length)loanPanel.append(node('p','No equipment is currently checked out.'));loanPanel.append(button('All loans & notes',()=>go('loans')));for(const e of equipment.filter(e=>e.blocker||e.condition&&e.condition!=='Ready').slice(0,6)){const p=node('p');p.append(button(e.name,()=>showItem(e.id)),node('small',e.blocker||e.condition,'sub'));reviewPanel.append(p)}reviewPanel.append(button('Browse equipment',()=>go('equipment')));split.append(loanPanel,reviewPanel);view.append(split)}
async function saveCheckoutCart(items,revision){const identity=context.identity,owner=scope();busy=true;try{const result=await api('checkout-cart',{items,revision,request_key:uuid()},identity);if(owner!==scope()||identity!==context?.identity)throw Error('The signed-in account changed. Reload the cart before continuing.');return result}finally{busy=false}}
async function checkoutCartPage(revision){await inventoryData();const state=await api('checkout-cart');if(revision!==routeVersion)return;title('Checkout cart','Review the saved equipment selection and confirm custody in Workshop.');view.append(message('This saved selection does not reserve equipment. Physically check each listed item before confirming.'));const rows=state.items.map(id=>{const item=equipment.find(e=>e.id===id);return [item?.name||'Unavailable equipment',item?.assetId||'',item?.condition||'Needs review',button('Remove',async()=>{const next=await saveCheckoutCart(state.items.filter(value=>value!==id),state.revision);if(revision!==routeVersion)return;Object.assign(state,next);await go('checkout-cart',false)})]});view.append(table(['Equipment','Asset code','Current condition','Action'],rows));view.append(actions(button('Add selected equipment',()=>go('equipment')),state.items.length?button('Review and confirm checkout',()=>checkoutConfirmDialog(state),'main'):null))}
async function checkoutConfirmDialog(state){const token=captureUi(),manifests=await Promise.all(state.items.map(id=>api('kit?id='+encodeURIComponent(id))));if(!uiCurrent(token))return;const entities=[],versions={},blockers=manifests.flatMap(kit=>kit.blockers||[]);for(const kit of manifests){for(const entity of kit.entities||[kit.root])if(!entities.some(row=>row.id===entity.id))entities.push(entity);Object.assign(versions,kit.versions||{})}const form=node('div',null,'form'),verified=new Set();form.append(node('p','Borrower: '+context.user.name+'. Confirm only after physically checking every item below. Kit components must all be verified.'));for(const item of entities)checkbox(form,'Physically verified: '+item.name,false,checked=>checked?verified.add(item.id):verified.delete(item.id));for(const blocked of blockers)form.append(message(blocked.name+': '+blocked.reason,'attention'));const confirm=button('Confirm checkout',async()=>{if(blockers.length)throw Error('Resolve checkout blockers before confirming.');if(entities.some(item=>!verified.has(item.id)))throw Error('Physically verify every listed item before confirming.');try{await write('checkout',{assets:entities.map(item=>item.id),verified:[...verified],kit_versions:versions,cart_revision:state.revision,cart_items:state.items,original_items:state.items,request_key:uuid()},'Confirm checkout',state.items.join(','));closeDialog(true);await go('checkout-cart',false);toast('Checkout recorded for '+entities.length+' equipment item(s).')}catch(error){await unresolvedOperation(error,'Checkout')}},'main');form.append(actions(button('Cancel',()=>closeDialog()),confirm));openDialog('Review checkout',form)}
async function equipmentPage(revision){await inventoryData();if(revision!==routeVersion)return;title('Equipment','Native Homebox inventory with borrowing and return context.',link('Manage inventory in Homebox','/'));const tools=node('div',null,'tools'),search=node('input');search.setAttribute('aria-label','Search equipment');search.placeholder='Search name, asset code, storage…';search.value=equipmentQuery;search.oninput=()=>{equipmentQuery=search.value;paintEquipment()};tools.append(search);const controls=node('div',null,'toolbar'),filter=node('select');filter.setAttribute('aria-label','Equipment filter');for(const [v,n] of [['','All equipment'],['available','Available'],['loan','Checked out'],['blocked','Needs review'],['archived','Archived']])filter.append(new Option(n,v));filter.value=equipmentFilter;filter.onchange=()=>{equipmentFilter=filter.value;paintEquipment()};controls.append(filter,node('span',selection.size+' selected','count'));controls.querySelector('span').id='selection-count';controls.append(button('Add selected to checkout cart',async()=>{if(!selection.size)throw Error('Select equipment first.');const state=await api('checkout-cart'),items=[...new Set([...state.items,...selection])],saved=items.length===state.items.length?state:await saveCheckoutCart(items,state.revision);selection.clear();toast(saved.items.length+' item(s) saved to your checkout cart.');await go('checkout-cart')}));if(manager())controls.append(button('Queue selected labels',()=>{if(!selection.size)throw Error('Select equipment first.');labelSelection=new Set(selection);go('labels')}));controls.append(button('Clear selection',()=>{selection.clear();paintEquipment()}));tools.append(controls);view.append(tools,node('div'));view.lastChild.id='equipment-table';paintEquipment()}
function paintEquipment(){const rows=equipment.filter(e=>(equipmentFilter==='archived'?e.archived:!e.archived)&&(equipmentFilter!=='loan'||held(e.id))&&(equipmentFilter!=='available'||!held(e.id)&&!e.blocker)&&(equipmentFilter!=='blocked'||e.blocker||e.condition&&e.condition!=='Ready')&&[e.name,e.assetId,address(e.parent?.id)].join(' ').toLowerCase().includes(equipmentQuery.toLowerCase()));const body=rows.map(e=>{const cb=node('input');cb.type='checkbox';cb.checked=selection.has(e.id);cb.setAttribute('aria-label','Select '+e.name);cb.onchange=()=>{cb.checked?selection.add(e.id):selection.delete(e.id);document.querySelector('#selection-count').textContent=selection.size+' selected'};const name=node('div');name.append(button(e.name,()=>showItem(e.id),'name'),node('small',e.assetId,'sub'));return [cb,name,address(e.parent?.id),tag(e.condition||'Unreviewed',e.condition==='Ready'?'ready':'warn'),tag(held(e.id)?'With '+held(e.id).borrower:'Available',held(e.id)?'loan':'')]});document.querySelector('#equipment-table').replaceChildren(table(['Select','Equipment','Assigned storage','Condition','Borrowing'],body));document.querySelector('#selection-count').textContent=selection.size+' selected'}
async function showItem(id,tab='summary'){const token=captureUi();const data=await api('entity?id='+encodeURIComponent(id));if(!uiCurrent(token))return;activeItem=data.entity;openDialog(activeItem.name);dialog.classList.add('drawer-wide');const tabs=node('div',null,'tabs');for(const [key,label] of [['summary','Summary'],['loan','Loan'],['notes','Return notes']])tabs.append(button(label,()=>itemTab(data,key),key===tab?'active':''));dialogBody.append(tabs,node('div'));dialogBody.lastChild.id='item-content';await itemTab(data,tab)}
async function itemTab(data,key){const target=document.querySelector('#item-content'),token=captureUi(),tabRevision=++itemTabVersion;if(!target)return;target.replaceChildren();dialogBody.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.textContent===({summary:'Summary',loan:'Loan',notes:'Return notes'})[key]));const e=data.entity;if(key==='summary'){target.append(node('p','Asset code: '+e.assetId),node('p','Assigned storage: '+address(e.parent?.id)),node('p','Condition: '+data.condition),node('p',data.blocker?'Checkout blocked: '+data.blocker:e.description||'No description'),link('Edit equipment in Homebox','/item/'+encodeURIComponent(e.id)),link('Photos & maintenance in Homebox','/item/'+encodeURIComponent(e.id)));if(manager())target.append(button('Review condition',()=>conditionDialog(data)),button('Preview equipment label',()=>previewLabel(e.id)));return}if(key==='loan'){const l=held(e.id);target.append(node('p',l?'Currently with '+l.borrower:'No current borrower.'),node('p','Assigned storage remains '+address(e.parent?.id)));if(l&&manager())target.append(button('Record administrative return',()=>returnDialog(e,l),'main'));return}const rows=await api('history?entity='+encodeURIComponent(e.id));if(!target.isConnected||!uiCurrent(token)||tabRevision!==itemTabVersion)return;const timeline=node('div',null,'timeline');for(const row of rows){for(const note of row.return_notes||[]){const a=node('article');a.append(node('p',note.text),node('small',note.author+' · '+timestamp(note.created_at)));timeline.append(a)}}if(!timeline.childNodes.length)timeline.append(node('p','No return notes recorded for this equipment.'));target.append(timeline)}
