function reviewImportRow(row){const batchId=importBatch.id,selectionRevision=importSelectionRevision;if(['creating','review','created'].includes(row.status))throw Error('This row has a saved operation. Inspect Recovery before editing or retrying.');const draft=clone(row.input),form=node('div',null,'form');form.append(node('p','CSV row '+row.csv_row+' · source ID '+(row.original.external_id||'not supplied')));for(const [key,label] of [['name','Equipment name'],['serial','Serial number'],['manufacturer','Manufacturer'],['model','Model'],['description','Description']])field(form,label,draft[key],key==='description'?'textarea':'text',v=>draft[key]=v);select(form,'Assigned location',[['','Choose a location'],...locations.map(l=>[l.id,l.name])],draft.location_id,v=>draft.location_id=v);select(form,'Equipment category',[['','Choose a category'],...types.map(t=>[t.id,t.name])],draft.type_id,v=>draft.type_id=v);select(form,'Condition',['Unreviewed','Ready','Needs Attention','Maintenance','Quarantined','Archived','Retired','Broken','Trashed'].map(v=>[v,v]),draft.import_condition,v=>draft.import_condition=v);checkbox(form,'Physically inspected and safe to use',draft.reviewed,v=>draft.reviewed=v);const save=async selected=>{const result=await write('imports/save',{id:batchId,index:row.index,input:draft,selected},'Save import review',batchId+':'+row.index);if(selectionRevision!==importSelectionRevision)return;importBatch=result;closeDialog(true);await renderBatch()};form.append(actions(button('Cancel',()=>closeDialog()),button('Skip this row',()=>save(false)),button('Save row review',()=>save(true),'main')));openDialog('Review imported equipment',form)}
function importActionDialog(action,rows){const batchId=importBatch.id;const selected=new Set(rows.map(r=>r.index)),form=node('div',null,'form'),progress=node('p');form.append(node('p',action==='create'?'Create reviewed equipment in Homebox. Existing records will not be overwritten.':'Print labels on the Pi label printer. Inspect physical stock before confirming.'));for(const row of rows)checkbox(form,row.input.name,true,value=>value?selected.add(row.index):selected.delete(row.index));let stop=false;const stopButton=button('Stop after current item',()=>{stop=true;stopButton.disabled=true});stopButton.dataset.queueStop='true';stopButton.hidden=true;form.append(progress,stopButton,actions(button('Cancel',()=>closeDialog()),button(action==='create'?'Confirm selected creation':'Confirm selected Pi labels',async()=>{if(!selected.size)throw Error('Select at least one item.');stopButton.hidden=false;let done=0;for(const row of rows.filter(r=>selected.has(r.index))){if(stop)break;progress.textContent=(action==='create'?'Creating ':'Printing ')+row.input.name;importBatch=await write('imports/'+action,{id:batchId,index:row.index,request_key:action==='create'?row.create_key:row.label_key},action==='create'?'Create imported equipment':'Print imported label',batchId+':'+row.index);done++}closeDialog(true);await renderBatch();toast(done+' item(s) completed. Saved progress is retained.');},'main')));openDialog(action==='create'?'Review selected creation':'Review selected Pi labels',form)}
async function recoveryPage(revision){const rows=await api('recovery');if(revision!==routeVersion)return;title('Recovery','Check saved outcomes and inspect equipment or physical labels before resolving them.');const pendingRows=pending();if(pendingRows.length)view.append(panel(node('h2','Actions awaiting confirmation'),...pendingRows.map(p=>{const line=node('div');line.append(node('p',p.label+' · '+timestamp(p.at)),button('Check saved result',()=>checkPending(p)));return line})));view.append(table(['Operation','Status','Equipment','Action'],rows.map(r=>[r.action,r.status,(r.native_assets||[]).map(e=>e.name).join(', ')||r.result_name||'',button('Inspect operation',()=>recoveryDialog(r))])))}
async function checkPending(p){const result=await api('operation/status',{request_key:p.key});const info=node('div');info.append(node('p',p.label+' · '+result.status));if(['completed','cancelled'].includes(result.status)){removePending(p.key);info.append(node('p','The saved outcome is confirmed. It will not be resubmitted.'),button('Return to recovery',()=>{closeDialog(true);go('recovery',false)}))}else if(result.status==='not_started'){info.append(node('p','The server has no started operation for this request. No automatic retry will be sent.'),button('Acknowledge no operation started',()=>{removePending(p.key);closeDialog(true);go('recovery',false)}))}else info.append(node('p','The outcome still needs inspection. Refresh the saved batch, layout or recovery list before another attempt. Do not repeat a physical print.'),button('Back to recovery',()=>closeDialog(true)));openDialog('Saved action result',info)}
function recoveryDialog(row){const form=node('div',null,'form');form.append(node('p','Operation: '+row.action+' · '+row.status),node('p','Saved ID: '+row.id),node('p','Started: '+timestamp(row.created_at)));if(row.intent&&Object.keys(row.intent).length){const intent=panel(node('h3','Saved request'));for(const [key,value] of Object.entries(row.intent))intent.append(node('p',key.replaceAll('_',' ')+': '+(value===null?'none':String(value))));form.append(intent);}for(const e of row.native_assets||[])form.append(node('p',e.name+' · '+(e.error||e.condition||'')+' · '+(e.parent||'')+' · record '+(e.id||'unavailable')));for(const s of row.context?.steps||[])form.append(node('p','Planned: '+(s.condition_after||'unchanged')+' · destination '+address(s.parent_after)));for(const n of row.return_notes||row.context?.return_notes||[])form.append(node('p','Return note: '+n.text));form.append(message('Inspect the physical result and native values. Finishing an uncertain print acknowledges inspected output; it must not blindly send another print.','attention'));let verified=false;checkbox(form,'I inspected physical equipment or labels and the stored values.',false,v=>verified=v);for(const outcome of ['complete','cancel'])form.append(button(outcome==='complete'?'Confirm completion':'Confirm safe cancellation',async()=>{if(!verified)throw Error('Inspect and confirm the physical result first.');await write('recovery/resolve',{id:row.id,outcome,native_job:!!row.native_job,desktop_job:!!row.desktop_job,inspected:true},'Resolve interrupted operation',row.id);closeDialog(true);await go('recovery',false);toast('Recovery decision saved.');}));form.append(button('Cancel',()=>closeDialog()));openDialog('Inspect interrupted operation',form)}
async function systemPage(revision){const data=await api('system');if(revision!==routeVersion)return;title('System','Pi services, printer readiness and private recovery backups.',button('Refresh status',()=>go('system',false)));const rows=[['Homebox',data.homebox+' · '+data.homebox_version],['Companion',data.companion],['Pi label printer',data.printer?.connected?'Connected · '+data.printer.width_mm+' × '+data.printer.height_mm+' mm stock':'Not ready'],['Camera devices on Pi',data.camera_devices],['Free storage',data.free_gb+' GB'],['Private backups',data.private_backups+(data.backup?' · '+data.backup.status:'')]];view.append(table(['System component','Current status'],rows));if(data.storage?.message)view.append(message(data.storage.message,'attention'));view.append(panel(node('p','Backups remain private on the Pi. Creating a consistent backup briefly pauses the kiosk and restarts it.'),button('Review recovery backup',()=>openDialog('Confirm private recovery backup',node('p','The kiosk briefly pauses and restarts. The archive stays private on the Pi.'),actions(button('Cancel',()=>closeDialog()),button('Confirm backup',async()=>{await write('backup/start',{},'Create private backup');closeDialog(true);toast('Backup started. Wait for service restart, then refresh status.');},'main'))))))}
